// Merge LinkedIn search results with candidate data
const exec = $('Split for LinkedIn Enrich').item.json;
const serperResponse = $input.item.json;

let linkedin_url = null;
let linkedin_snippet = null;

if (serperResponse && serperResponse.organic && Array.isArray(serperResponse.organic)) {
  const topResult = serperResponse.organic[0];
  if (topResult && topResult.link && topResult.link.includes('linkedin.com/in/')) {
    linkedin_url = topResult.link;
    linkedin_snippet = (topResult.snippet || '').substring(0, 500);
  }
}

return [{ json: { ...exec, linkedin_url, linkedin_snippet } }];
